design.css:
/* Crunchy Deck for izumi. Sizes are Crunchy Deck's own CSS px times --cd: Crunchy Deck runs at a
   1.5x page zoom on the Steam Deck and izumi's Game mode at 1.25x, so Game mode scales them by 1.2. */
:scope {
  --cd: 1px;
  --cd-brand: #f47521;
  --cd-surface: #0a0a0a;
  --cd-s1: #141414;
  --cd-s2: #1e1e1e;
  --cd-s3: #2a2a2a;
}
:scope.gamemode { --cd: 1.2px; }
/* Crisp play and replay icons: the ▶ and ↻ characters fall back to a soft font on the Deck. */
:scope {
  --cd-play-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20fill%3D%27white%27%20d%3D%27M8%205.14v13.72a1%201%200%200%200%201.52.85l11.07-6.86a1%201%200%200%200%200-1.7L9.52%204.29A1%201%200%200%200%208%205.14z%27%2F%3E%3C%2Fsvg%3E");
  --cd-replay-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27white%27%20stroke-width%3D%272.5%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27M3%2012a9%209%200%201%200%209-9%209.75%209.75%200%200%200-6.74%202.74L3%208%27%2F%3E%3Cpath%20d%3D%27M3%203v5h5%27%2F%3E%3C%2Fsvg%3E");
}
:scope { background: var(--cd-surface); }

/* ---- Drawer navigation -------------------------------------------------------------------- */
[data-slot="nav.drawer"] {
  width: calc(288 * var(--cd));
  gap: calc(2 * var(--cd));
  padding: calc(24 * var(--cd)) calc(12 * var(--cd)) 0;
  border: 0;
  background: var(--cd-s1);
  box-shadow: 0 25px 50px -12px rgb(0 0 0 / 0.25);
}
[data-part="nav.drawer.head"] {
  margin: 0;
  padding: 0 calc(8 * var(--cd)) calc(16 * var(--cd));
  gap: calc(12 * var(--cd));
  color: #fff;
}
[data-slot="nav.drawer"] [data-part="nav.item"] {
  position: relative;
  height: auto;
  min-height: 0;
  flex-shrink: 0;
  gap: calc(12 * var(--cd));
  padding: calc(10 * var(--cd)) calc(12 * var(--cd));
  border-radius: calc(12 * var(--cd));
  background: transparent;
  color: rgb(255 255 255 / 0.55);
  font-size: calc(15 * var(--cd));
  font-weight: 700;
  transition: transform 150ms, background-color 150ms, box-shadow 150ms, color 150ms;
}
[data-slot="nav.drawer"] [data-part="nav.item"][data-active] { background: transparent; color: #fff; }
[data-slot="nav.drawer"] [data-part="nav.item"][data-active]::after {
  content: '';
  margin-left: auto;
  width: calc(6 * var(--cd));
  height: calc(6 * var(--cd));
  border-radius: 9999px;
  background: var(--cd-brand);
}
[data-slot="nav.drawer"] [data-part="nav.item.icon"] { width: auto; color: rgb(255 255 255 / 0.45); transition: color 150ms; }
[data-slot="nav.drawer"] [data-part="nav.item.icon"] svg { width: calc(20 * var(--cd)); height: calc(20 * var(--cd)); }
[data-slot="nav.drawer"] [data-part="nav.item"][data-active] [data-part="nav.item.icon"] { color: var(--cd-brand); }
[data-slot="nav.drawer"] [data-part="nav.item"]:is(:focus-visible), :scope:not(.gamemode) [data-slot="nav.drawer"] [data-part="nav.item"]:hover {
  transform: scale(1.02);
  outline: none;
  background: rgb(244 117 33 / 0.15);
  color: #fff;
  box-shadow: inset 0 0 0 1.5px var(--cd-brand);
}
[data-slot="nav.drawer"] [data-part="nav.item"]:is(:focus-visible) [data-part="nav.item.icon"], :scope:not(.gamemode) [data-slot="nav.drawer"] [data-part="nav.item"]:hover [data-part="nav.item.icon"] { color: var(--cd-brand); }
[data-part="nav.drawer.heading"] {
  margin: 0;
  padding: calc(16 * var(--cd)) calc(12 * var(--cd)) calc(4 * var(--cd));
  color: rgb(255 255 255 / 0.3);
  font-size: calc(10 * var(--cd));
  font-weight: 800;
  letter-spacing: 0.14em;
}
[data-part="nav.drawer.foot"] {
  margin: auto calc(-12 * var(--cd)) 0;
  padding: calc(12 * var(--cd));
  gap: calc(8 * var(--cd));
  border-top: 1px solid rgb(255 255 255 / 0.1);
}
[data-part="nav.drawer.foot"] [data-part="nav.action"] {
  border-radius: calc(12 * var(--cd));
  color: rgb(255 255 255 / 0.55);
  transition: background-color 150ms, box-shadow 150ms, color 150ms;
}
[data-part="nav.drawer.foot"] [data-action="account"] { padding: calc(8 * var(--cd)); gap: calc(12 * var(--cd)); color: #fff; font-size: calc(14 * var(--cd)); font-weight: 700; }
[data-part="nav.drawer.foot"] [data-action="account"] [data-part="nav.action.icon"] { width: calc(36 * var(--cd)); height: calc(36 * var(--cd)); }
[data-part="nav.drawer.foot"] [data-action="account"] img { width: 100%; height: 100%; border-radius: calc(8 * var(--cd)); box-shadow: 0 0 0 1px rgb(255 255 255 / 0.1); }
[data-part="nav.drawer.foot"] :is([data-action="settings"], [data-action="incognito"]) { width: calc(44 * var(--cd)); height: calc(44 * var(--cd)); }
[data-part="nav.drawer.foot"] [data-action="settings"][data-active] { color: var(--cd-brand); }
[data-part="nav.drawer.foot"] [data-part="nav.action"]:is(:focus-visible), :scope:not(.gamemode) [data-part="nav.drawer.foot"] [data-part="nav.action"]:hover {
  outline: none;
  background: rgb(244 117 33 / 0.15);
  color: var(--cd-brand);
  box-shadow: inset 0 0 0 1.5px var(--cd-brand);
}
[data-part="nav.drawer.foot"] [data-action="account"]:is(:focus-visible), :scope:not(.gamemode) [data-part="nav.drawer.foot"] [data-action="account"]:hover { background: rgb(255 255 255 / 0.05); color: #fff; }
[data-part="nav.menu"] { border-radius: 9999px; background: rgb(0 0 0 / 0.5); color: #fff; }

/* ---- Featured banner ---------------------------------------------------------------------- */
[data-slot="home.hero"] { background: var(--cd-surface); }
[data-part="cd-hero"] { height: 100%; }
[data-part="cd-hero-art"]::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(to top, rgb(10 10 10 / 0.9), transparent 50%, transparent),
    linear-gradient(to right, #0a0a0a, rgb(10 10 10 / 0.6) 50%, transparent);
}
[data-part="cd-hero-art"] img { transition: opacity 700ms; }
[data-part="cd-hero-body"] {
  left: calc(40 * var(--cd)) !important;
  bottom: calc(40 * var(--cd)) !important;
  width: 48%;
  max-width: 48%;
  gap: 0;
  padding: 0 !important;
}
[data-part="cd-hero-logo"] { width: 70% !important; height: calc(96 * var(--cd)); margin-bottom: calc(16 * var(--cd)); overflow: visible; filter: drop-shadow(0 10px 8px rgb(0 0 0 / 0.04)) drop-shadow(0 4px 3px rgb(0 0 0 / 0.1)); }
[data-part="cd-hero-logo"] img { object-fit: contain; object-position: left bottom; }
[data-part="cd-hero-title"] { margin-bottom: calc(12 * var(--cd)); font-size: calc(36 * var(--cd)); font-weight: 900; line-height: 1.1; text-shadow: 0 2px 8px rgb(0 0 0 / 0.5); }
[data-part="cd-hero-meta"] {
  min-height: calc(28 * var(--cd));
  margin-bottom: calc(12 * var(--cd));
  align-items: center;
  gap: calc(4 * var(--cd)) calc(8 * var(--cd));
  font-size: calc(14 * var(--cd));
  line-height: 1.43;
}
[data-part="cd-genres"] { gap: 0; align-items: center; }
[data-part="cd-comma"] { margin-right: 0.3em; color: rgb(255 255 255 / 0.75); }
[data-part="cd-rating"] {
  padding: calc(2 * var(--cd)) calc(6 * var(--cd));
  border: 1px solid rgb(255 255 255 / 0.45);
  border-radius: calc(4 * var(--cd));
  color: #fff;
  font-size: calc(12 * var(--cd));
  font-weight: 700;
  line-height: 1.33;
}
[data-part="cd-sep"] { color: rgb(255 255 255 / 0.4); font-size: calc(9.6 * var(--cd)); line-height: 1; user-select: none; }
[data-part="cd-meta-text"] { color: rgb(255 255 255 / 0.75); }
[data-part="cd-hero-synopsis"] {
  display: -webkit-box;
  max-width: calc(576 * var(--cd));
  margin-bottom: calc(20 * var(--cd));
  overflow: hidden;
  color: rgb(255 255 255 / 0.8);
  font-size: calc(14 * var(--cd));
  line-height: 1.43;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
[data-part="cd-hero-actions"] { gap: calc(12 * var(--cd)); align-items: center; }
[data-part="cd-play"], [data-part="cd-details"] {
  min-height: 0 !important;
  gap: calc(8 * var(--cd)) !important;
  border-radius: calc(8 * var(--cd)) !important;
  font-size: calc(16 * var(--cd)) !important;
  line-height: 1.5;
  transition: box-shadow 150ms, background-color 150ms;
}
[data-part="cd-play"] { line-height: calc(28 * var(--cd)) !important; padding: calc(12 * var(--cd)) calc(28 * var(--cd)) !important; background: var(--cd-brand) !important; color: #000 !important; font-weight: 700 !important; }
[data-part="cd-play"] svg { width: calc(18 * var(--cd)); height: calc(18 * var(--cd)); }
[data-part="cd-details"] { line-height: calc(24 * var(--cd)) !important; padding: calc(12 * var(--cd)) calc(20 * var(--cd)) !important; background: rgb(255 255 255 / 0.15) !important; color: #fff !important; font-weight: 600 !important; }
[data-part="cd-play"]:is(:focus, :focus-visible), :scope:not(.gamemode) [data-part="cd-play"]:hover { outline: none !important; filter: none !important; box-shadow: 0 0 0 calc(4 * var(--cd)) rgb(255 255 255 / 0.4); }
[data-part="cd-details"]:is(:focus, :focus-visible), :scope:not(.gamemode) [data-part="cd-details"]:hover { outline: none !important; filter: none !important; background: rgb(255 255 255 / 0.3) !important; box-shadow: 0 0 0 calc(4 * var(--cd)) rgb(255 255 255 / 0.3); }
[data-slot="home.hero"] [data-part="hero.indicator"] {
  position: absolute;
  inset: auto calc(24 * var(--cd)) calc(16 * var(--cd)) auto;
  display: flex;
  gap: calc(8 * var(--cd));
  padding: 0;
}
[data-slot="home.hero"] [data-part="hero.dot"] { padding: 0; }
[data-slot="home.hero"] [data-part="hero.dot.track"] {
  width: calc(8 * var(--cd));
  height: calc(8 * var(--cd));
  border-radius: 9999px;
  background: rgb(255 255 255 / 0.4);
  transition: width 300ms, background-color 300ms;
}
[data-slot="home.hero"] [data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { width: calc(40 * var(--cd)); background: rgb(255 255 255 / 0.3); }
/* The arrows only show while the pointer is over the banner, as in Crunchy Deck. */
[data-slot="home.hero"] [data-part="hero.edge"] {
  width: calc(48 * var(--cd));
  height: calc(48 * var(--cd));
  border-radius: 9999px;
  background: rgb(0 0 0 / 0.5);
  color: #fff;
  opacity: 0 !important;
  transition: opacity 200ms;
}
:scope:not(.gamemode) [data-slot="home.hero"]:hover [data-part="hero.edge"] { opacity: 1 !important; }

/* ---- Rows and cards ----------------------------------------------------------------------- */
[data-slot="home"] [data-slot="row"] { margin-bottom: calc(20 * var(--cd)); }
[data-slot="row"] [data-part="row.header"] { margin-bottom: calc(6 * var(--cd)); padding-inline: calc(40 * var(--cd)); }
[data-slot="row"] [data-part="row.title"] { color: rgb(255 255 255 / 0.8); font-size: calc(18 * var(--cd)); font-weight: 700; line-height: 1.55; }
[data-slot="row"] [data-part="row.track"] {
  gap: calc(16 * var(--cd)) !important;
  padding: calc(8 * var(--cd)) calc(40 * var(--cd)) calc(32 * var(--cd));
  scroll-padding-inline: calc(40 * var(--cd));
}
[data-part="card"] { width: calc(195 * var(--cd)) !important; }
[data-part="card"][data-shape="episode"] { width: calc(266 * var(--cd)) !important; }
[data-part="card"] > a {
  position: relative;
  display: block;
  width: 100% !important;
  overflow: hidden;
  border-radius: calc(12 * var(--cd));
  background: var(--cd-s2);
  transition: transform 150ms ease-out, box-shadow 150ms ease-out, opacity 150ms ease;
}
[data-part="card"] [data-part="card.art"] { height: calc(290 * var(--cd)); aspect-ratio: auto !important; border-radius: 0; background: var(--cd-s2); }
[data-part="card"][data-shape="episode"] [data-part="card.art"] { height: calc(150 * var(--cd)); }
[data-part="card"] [data-part="card.art"] { z-index: auto !important; transform: none !important; box-shadow: none !important; outline: none !important; }
[data-part="card"] [data-part="card.art"] img { transform: none !important; }
[data-part="card"] a > div:has(> [data-part="card.title"]) {
  position: absolute;
  inset: auto 0 0 0;
  display: flex;
  flex-direction: column-reverse;
  min-height: 0;
  padding: calc(24 * var(--cd)) calc(8 * var(--cd)) calc(8 * var(--cd));
  z-index: 2;
  pointer-events: none;
  background-image: linear-gradient(to top, rgb(0 0 0 / 0.9), transparent);
}
[data-part="card.title"] { margin: 0; color: #fff; font-size: calc(12 * var(--cd)); font-weight: 700; line-height: 1.25; text-align: left; }
[data-part="card.title"] > span:first-child:empty { display: none; }
[data-part="card.meta"] { margin: 0 0 calc(2 * var(--cd)); color: rgb(255 255 255 / 0.8); font-size: calc(11 * var(--cd)); font-weight: 600; }
[data-part="card"]:not([data-shape="episode"]) [data-part="card.meta"] { display: none; }
[data-part="card.score"], [data-part="card.badge"] { display: none; }
[data-part="card.progress"] { z-index: 5; height: calc(4 * var(--cd)); background: rgb(255 255 255 / 0.25); }
/* Hover counts outside Game mode only: there the cursor rests wherever it was left. */
[data-part="card"] > a:is(:focus, :focus-visible),
:scope:not(.gamemode) [data-part="card"] > a:hover {
  outline: none !important;
  transform: scale(1.05);
  box-shadow: 0 0 0 3px var(--cd-brand), 0 14px 34px rgb(0 0 0 / 0.65) !important;
}
[data-slot="row"]:focus-within [data-part="card"] > a:not(:focus) { opacity: 0.82; }
[data-part="card.progress"] { z-index: 3; }
/* The play affordance over the focused card. */
[data-part="card"] > a [data-part="card.art"]::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: calc(48 * var(--cd));
  height: calc(48 * var(--cd));
  border-radius: 9999px;
  background: rgb(0 0 0 / 0.6) var(--cd-play-icon) center / calc(22 * var(--cd)) no-repeat;
  opacity: 0;
  transform: translate(-50%, -50%);
  transition: opacity 150ms;
  pointer-events: none;
}
[data-part="card"] > a:is(:focus, :focus-visible) [data-part="card.art"]::after,
:scope:not(.gamemode) [data-part="card"] > a:hover [data-part="card.art"]::after { opacity: 1; }

/* ---- Title page --------------------------------------------------------------------------- */
[data-slot="detail.banner"] { height: 58vh; min-height: 58vh !important; }
/* Crunchy Deck's title page has no Back button: B goes back. Pointer windows keep izumi's. */
:scope.gamemode [data-slot="detail.banner"] > button[aria-label="Back"] { display: none; }
[data-part="detail.backdrop"] { transition: opacity 500ms; }
[data-part="detail.scrim"][data-dir="left"] { background-image: linear-gradient(to right, #0a0a0a, rgb(10 10 10 / 0.6) 50%, transparent); }
[data-part="detail.scrim"][data-dir="bottom"] { background-image: linear-gradient(to top, #0a0a0a, transparent 50%, transparent); }
[data-slot="detail.banner"] > div:has(> [data-part="detail.body"]) { min-height: 58vh; max-width: none; padding: 0 0 calc(32 * var(--cd)) calc(40 * var(--cd)); }
[data-part="detail.body"] { max-width: 55%; flex: none; }
[data-part="detail.title"] {
  width: auto !important;
  height: auto !important;
  margin-bottom: calc(12 * var(--cd));
  font-size: calc(36 * var(--cd));
  font-weight: 900;
  line-height: 1.1;
  text-shadow: 0 2px 8px rgb(0 0 0 / 0.5);
}
/* A long name at full size took three lines up to the top of the screen. */
[data-part="detail.title"][data-length="long"] {
  display: -webkit-box;
  overflow: hidden;
  font-size: calc(26 * var(--cd));
  line-height: 1.15;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}
[data-part="detail.logo"] { display: none; }
[data-part="detail.title"][aria-label]::after { content: attr(aria-label); }
[data-part="detail.meta"], [data-part="detail.genres"] { display: none; }
[data-part="detail.body"] > div:has(> [data-part="ratings"]), [data-part="detail.body"] > .mt-3:not([data-part]) { display: none; }
[data-part="detail.synopsis"] {
  max-width: none;
  margin: 0 0 calc(20 * var(--cd));
  color: rgb(255 255 255 / 0.75);
  font-size: calc(14 * var(--cd));
  line-height: 1.43;
  -webkit-line-clamp: 3;
}
[data-part="detail.actions"] { margin-top: 0; gap: calc(12 * var(--cd)); }
[data-part="detail.actions"] > :not([data-action="play"]):not([data-action="watchlist"]):not([data-action="more"]) { display: none; }
[data-part="detail.actions"] > [data-action="more"] { order: 9; }
[data-part="detail.actions"] > [data-action] {
  gap: calc(8 * var(--cd));
  border-radius: calc(8 * var(--cd));
  padding: calc(12 * var(--cd)) calc(20 * var(--cd));
  font-size: calc(16 * var(--cd));
  font-weight: 700;
  line-height: 1.5;
  transition: box-shadow 150ms;
}
[data-part="detail.actions"] > [data-action="play"] { padding-inline: calc(28 * var(--cd)); background: var(--cd-brand); color: #000; }
[data-part="detail.actions"] > :is([data-action="watchlist"], [data-action="more"]) { background: rgb(30 30 30 / 0.9); color: #fff; }
[data-part="detail.actions"] > [data-action="more"] { width: calc(48 * var(--cd)); height: calc(48 * var(--cd)); padding: 0; }
[data-part="detail.actions"] > [data-action="watchlist"] svg { color: inherit; }
/* As tall as Continue: izumi gives the button a fixed height, Crunchy Deck pads both alike. */
[data-part="detail.actions"] > [data-action="watchlist"] { height: auto; }
[data-part="detail.actions"] > [data-action="play"]:is(:focus-visible), :scope:not(.gamemode) [data-part="detail.actions"] > [data-action="play"]:hover { outline: none; box-shadow: 0 0 0 calc(4 * var(--cd)) rgb(255 255 255 / 0.4); }
[data-part="detail.actions"] > :is([data-action="watchlist"], [data-action="more"]):is(:focus-visible), :scope:not(.gamemode) [data-part="detail.actions"] > :is([data-action="watchlist"], [data-action="more"]):hover { outline: none; box-shadow: 0 0 0 calc(4 * var(--cd)) rgb(255 255 255 / 0.3); }

[data-slot="detail.section"][data-section="episodes"] { margin-top: 0; }
/* Crunchy Deck's series page has no details section; with genres hidden it showed only its heading. */
[data-slot="detail.section"][data-section="overview"] { display: none; }
[data-slot="detail.section"][data-section="episodes"] > [data-part="detail.section-title"] { display: none; }
[data-slot="detail.episodes"] { margin-top: 0; padding: calc(12 * var(--cd)) calc(40 * var(--cd)) calc(64 * var(--cd)); }
[data-slot="episodes.toolbar"] { gap: calc(8 * var(--cd)); margin-bottom: calc(24 * var(--cd)); }
[data-part="episodes.heading"] { display: none; }
[data-slot="episodes.seasons"] { gap: calc(8 * var(--cd)); margin: 0; padding: 0; flex-wrap: wrap; overflow: visible; }
/* Controls under the season pills sit like a second line of pills (Crunchy Deck's flex-wrap gap-2). */
[data-slot="episodes.seasons"] + [data-slot="episodes.toolbar"] { margin-top: calc(8 * var(--cd)); }
/* Crunchy Deck's pill: its season pills, and its sort pills (Browse page, the same classes), which
   Oldest | Newest copies; the round search and download buttons are pills of the same height. */
:is([data-part="season"], [data-part="episodes.sort"] > button, [data-slot="episodes.toolbar"] button:is([data-part="episodes.search"], [data-part="episodes.download"])) {
  padding: calc(6 * var(--cd)) calc(16 * var(--cd));
  border: 0;
  border-radius: 9999px;
  background: var(--cd-s2);
  color: rgb(255 255 255 / 0.8);
  font-size: calc(14 * var(--cd));
  font-weight: 600;
  line-height: calc(20 * var(--cd));
  transition: box-shadow 150ms;
}
:is([data-part="season"], [data-part="episodes.sort"] > button, [data-slot="episodes.toolbar"] button[data-part="episodes.search"])[data-active] { background: var(--cd-brand); color: #000; }
[data-part="season.label"] { font-size: inherit; font-weight: inherit; line-height: inherit; }
[data-part="season.year"] { display: none; }
:is([data-part="season"], [data-part="episodes.sort"] > button, [data-slot="episodes.toolbar"] button:is([data-part="episodes.search"], [data-part="episodes.download"])):is(:focus-visible),
:scope:not(.gamemode) :is([data-part="season"], [data-part="episodes.sort"] > button, [data-slot="episodes.toolbar"] button:is([data-part="episodes.search"], [data-part="episodes.download"])):hover { outline: none; box-shadow: 0 0 0 2px var(--cd-brand); }
[data-part="episodes.sort"][data-variant="tabs"] { height: auto; gap: calc(8 * var(--cd)); padding: 0; border-radius: 0; background: transparent; }
[data-slot="episodes.toolbar"] button:is([data-part="episodes.search"], [data-part="episodes.download"]) { width: calc(32 * var(--cd)); height: calc(32 * var(--cd)); padding: 0; }
[data-slot="episodes.toolbar"] button:is([data-part="episodes.search"], [data-part="episodes.download"]) svg { width: calc(16 * var(--cd)); height: calc(16 * var(--cd)); }
/* Crunchy Deck's grid-cols-2 md:grid-cols-3 xl:grid-cols-4: three across on the Deck, four on a wide window. */
[data-slot="detail.episodes"] [data-part="episodes.grid"] {
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
