   Crunchy Deck's Play and Back and Game mode's own buttons do; Play and Back fill on hover too. */
[data-slot="player.controls"][data-variant="desktop"] :is([data-part="player.control"], [data-part="button"][data-control]):focus-visible,
:scope.controller-mode [data-slot="player.controls"][data-variant="desktop"] :is([data-part="player.control"], [data-part="button"][data-control]):focus,
[data-slot="player.controls"][data-variant="desktop"] :is([data-control="play"], [data-control="back"]):hover {
  outline: none;
  transform: none;
  background: var(--cd-brand);
  color: #000;
  box-shadow: none;
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.volume"] { accent-color: var(--cd-brand); }
/* Options, audio/subtitles and right-click menus: Crunchy Deck's 256px panel in surface-1/95 with a
   white/10 ring; rows lift to white/15, and the focused row gets the house orange edge (options.item).
   Rows are Crunchy Deck's 40px (py-2.5 around a 20px line) with 16px sides and close once chosen: theme.json
   player.menu (Theme API 9). */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.menu"] {
  width: calc(256 * var(--cd));
  border: 0;
  border-radius: calc(12 * var(--cd));
  background: rgb(20 20 20 / 0.95);
  box-shadow: 0 0 0 1px rgb(255 255 255 / 0.1), 0 25px 50px -12px rgb(0 0 0 / 0.25);
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.menu"] button { color: rgb(255 255 255 / 0.85); }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.menu"] button:hover { background: rgb(255 255 255 / 0.15); }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.menu"] button:focus-visible,
:scope.controller-mode [data-slot="player.controls"][data-variant="desktop"] [data-part="player.menu"] button:focus {
  outline: none;
  transform: none;
  background: rgb(255 255 255 / 0.15);
  color: #fff;
  box-shadow: inset calc(4 * var(--cd)) 0 0 var(--cd-brand);
}
/* The chosen option is bold in Crunchy Deck orange, focused or not (font-bold text-brand). */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.menu"] [data-part="player.menu.item"][data-state="active"] { color: var(--cd-brand); font-weight: 700; }
/* Skip: Crunchy Deck's white pill with a double chevron, orange with a white/40 ring when chosen. */
button[data-part="player.skip"] {
  border: 0;
  border-radius: calc(6 * var(--cd));
  padding: calc(10 * var(--cd)) calc(20 * var(--cd));
  background: rgb(255 255 255 / 0.9);
  color: #000;
  font-size: calc(14 * var(--cd));
  font-weight: 900;
  box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}
button[data-part="player.skip"]::after {
  content: '';
  display: inline-block;
  width: 1em;
  height: 1em;
  margin-left: 0.3em;
  vertical-align: -0.15em;
  background: var(--cd-skip-icon) center / contain no-repeat;
}
button[data-part="player.skip"]:is(:hover, :focus-visible), :scope.controller-mode button[data-part="player.skip"]:focus {
  outline: none;
  transform: none;
  background: var(--cd-brand);
  box-shadow: 0 0 0 calc(4 * var(--cd)) rgb(255 255 255 / 0.4), 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}
/* Up Next: Crunchy Deck's next-episode card, an 80x48 still beside the text, docked over the bottom
   right corner without the dim (phone widths keep izumi's bottom placement). */
@media (min-width: 640px) {
  [role="dialog"]:has(> [data-part="player.upnext"]) {
    align-items: flex-end;
    justify-content: flex-end;
    padding: 0 calc(32 * var(--cd)) calc(112 * var(--cd));
    background: transparent;
  }
}
[data-part="player.upnext"] {
  display: flex;
  align-items: center;
  gap: calc(12 * var(--cd));
  width: auto;
  padding: calc(12 * var(--cd)) calc(20 * var(--cd)) calc(12 * var(--cd)) calc(12 * var(--cd));
  border: 0;
  border-radius: calc(8 * var(--cd));
  background: rgb(20 20 20 / 0.95);
  box-shadow: 0 0 0 1px rgb(255 255 255 / 0.1), 0 25px 50px -12px rgb(0 0 0 / 0.25);
}
[data-part="player.upnext.art"] { flex: none; width: calc(80 * var(--cd)); height: calc(48 * var(--cd)); border-radius: calc(4 * var(--cd)); }
[data-part="player.upnext.art"] > :not(img) { display: none; }
[data-part="player.upnext"] > :has(> [data-part="player.upnext.kicker"]) { min-width: 0; padding: 0; }
[data-part="player.upnext.kicker"] { color: rgb(255 255 255 / 0.5); font-size: calc(12 * var(--cd)); font-weight: 600; letter-spacing: 0.025em; }
[data-part="player.upnext.title"] {
  display: -webkit-box;
  margin-top: 0;
  overflow: hidden;
  font-size: calc(14 * var(--cd));
  font-weight: 700;
  line-height: calc(20 * var(--cd));
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
}
[data-part="player.upnext.countdown"] { margin-top: 0; color: rgb(255 255 255 / 0.5); font-size: calc(12 * var(--cd)); }
/* Its buttons: Crunchy Deck's small text buttons, Play now in orange. */
[data-part="player.upnext"] :has(> [data-control="upnext-play"]) { flex-direction: row; justify-content: flex-start; gap: calc(8 * var(--cd)); margin-top: calc(12 * var(--cd)); }
[data-part="player.upnext"] [data-part="player.control"] {
  height: auto;
  padding: calc(8 * var(--cd)) calc(12 * var(--cd));
  border-radius: calc(6 * var(--cd));
  font-size: calc(14 * var(--cd));
  font-weight: 600;
  transition: background-color 150ms, color 150ms, box-shadow 150ms;
}
[data-part="player.upnext"] [data-control="upnext-stay"] { color: rgb(255 255 255 / 0.9); }
[data-part="player.upnext"] [data-control="upnext-stay"]:hover { background: rgb(255 255 255 / 0.2); }
[data-part="player.upnext"] [data-control="upnext-play"] { background: var(--cd-brand); color: #000; font-weight: 700; }
[data-part="player.upnext"] [data-control="upnext-stay"]:focus-visible, :scope.controller-mode [data-part="player.upnext"] [data-control="upnext-stay"]:focus { outline: none; background: var(--cd-brand); color: #000; box-shadow: none; }
[data-part="player.upnext"] [data-control="upnext-play"]:is(:hover, :focus-visible), :scope.controller-mode [data-part="player.upnext"] [data-control="upnext-play"]:focus { outline: none; box-shadow: 0 0 0 calc(4 * var(--cd)) rgb(255 255 255 / 0.4); }
